var a=[{slug:"diagnostyka-bolu-brzucha",nazwa:"Diagnostyka B\xF3lu brzucha",kategoria:"Pakiet diagnostyczny",lead:"Kompleksowy pakiet diagnostyczny obejmuj\u0105cy konsultacj\u0119, przygotowanie i badanie endoskopowe w znieczuleniu og\xF3lnym.",bloki:[{typ:"ul",items:["Konsultacja lekarska + badania krwi","Proces przeczyszczenia si\u0119 do zabiegu wraz z noclegiem (mo\u017Cliwo\u015B\u0107 zabrania osoby towarzysz\u0105cej)","Kolonoskopia + Gastroskopia w znieczuleniu og\xF3lnym","Pobranie wycinka do bada\u0144 histopatologicznych, ma\u0142a polipektomia","Konsultacja lekarska po otrzymaniu wynik\xF3w histopatologicznych (ok. miesi\u0105c po badaniu)"]},{typ:"cena",text:"3499z\u0142"},{typ:"linki",items:[{label:"Jak si\u0119 przygotowa\u0107 do Kolonoskopii?",link:"/pracownia-endoskopii/kolonoskopia"},{label:"Jak si\u0119 przygotowa\u0107 do Gastroskopii?",link:"/pracownia-endoskopii/gastroskopia"}]}]},{slug:"pomiar-tetna-i-cisnienia",nazwa:"Pomiar t\u0119tna i ci\u015Bnienia",kategoria:"Kardiologia",lead:"Jedno z najcz\u0119stszych bada\u0144 diagnostycznych oceniaj\u0105cych funkcjonowanie uk\u0142adu sercowo-naczyniowego.",bloki:[{typ:"p",text:"Pomiar ci\u015Bnienia krwi oraz t\u0119tna jest jednym z najcz\u0119stszych bada\u0144 diagnostycznych, kt\xF3re pomagaj\u0105 oceni\u0107 funkcjonowanie uk\u0142adu sercowo-naczyniowego."},{typ:"p",text:"Regularne monitorowanie tych parametr\xF3w jest szczeg\xF3lnie istotne dla os\xF3b z nadci\u015Bnieniem t\u0119tniczym, cukrzyc\u0105, chorobami serca oraz dla wszystkich dbaj\u0105cych o zdrowy tryb \u017Cycia."}]},{slug:"pomiar-masy-ciala",nazwa:"Pomiar masy cia\u0142a",kategoria:"Diagnostyka og\xF3lna",lead:"Szybkie i bezbolesne badanie wykonywane przy u\u017Cyciu certyfikowanej wagi medycznej.",bloki:[{typ:"h4",text:"Na czym polega badanie?"},{typ:"p",text:"Pomiar masy cia\u0142a wykonywany jest przy u\u017Cyciu certyfikowanej wagi medycznej. Badanie jest szybkie, bezbolesne i nie wymaga specjalnego przygotowania."},{typ:"h4",text:"Cel badania"},{typ:"ul",items:["ocena aktualnej masy cia\u0142a","monitorowanie zmian masy cia\u0142a w czasie","kontrola skuteczno\u015Bci leczenia dietetycznego","ocena ryzyka nadwagi, oty\u0142o\u015Bci lub niedo\u017Cywienia","wsparcie diagnostyki w chorobach metabolicznych, gastroenterologicznych, kardiologicznych i endokrynologicznych"]},{typ:"h4",text:"Przebieg badania"},{typ:"p",text:"Pacjent staje na wadze w lekkim ubraniu, bez obuwia. Wynik odczytywany jest natychmiast i mo\u017Ce zosta\u0107 wykorzystany do wyliczenia wska\u017Anika BMI lub por\xF3wnania z wcze\u015Bniejszymi pomiarami."},{typ:"h4",text:"Dla kogo?"},{typ:"p",text:"Badanie zalecane jest osobom:"},{typ:"ul",items:["kontroluj\u0105cym mas\u0119 cia\u0142a","korzystaj\u0105cym z opieki dietetycznej","z chorobami przewlek\u0142ymi wp\u0142ywaj\u0105cymi na wag\u0119","monitoruj\u0105cym efekty leczenia lub zmiany stylu \u017Cycia"]},{typ:"p",text:"Czas badania: oko\u0142o 1-2 minuty."},{typ:"h4",text:"Przygotowanie do badania"},{typ:"p",text:"Nie jest wymagane specjalne przygotowanie. Dla uzyskania najbardziej por\xF3wnywalnych wynik\xF3w zaleca si\u0119 wykonywanie pomiar\xF3w o podobnej porze dnia."}]},{slug:"pobranie-krwi",nazwa:"Pobranie krwi",kategoria:"Diagnostyka laboratoryjna",lead:"Jedno z najcz\u0119stszych bada\u0144 diagnostycznych oceniaj\u0105cych funkcjonowanie uk\u0142adu sercowo-naczyniowego.",bloki:[{typ:"p",text:"Pomiar ci\u015Bnienia krwi oraz t\u0119tna jest jednym z najcz\u0119stszych bada\u0144 diagnostycznych, kt\xF3re pomagaj\u0105 oceni\u0107 funkcjonowanie uk\u0142adu sercowo-naczyniowego."},{typ:"p",text:"Regularne monitorowanie tych parametr\xF3w jest szczeg\xF3lnie istotne dla os\xF3b z nadci\u015Bnieniem t\u0119tniczym, cukrzyc\u0105, chorobami serca oraz dla wszystkich dbaj\u0105cych o zdrowy tryb \u017Cycia."}]},{slug:"badanie-holtera",nazwa:"Badanie Holtera",kategoria:"Kardiologia",lead:"Ci\u0105g\u0142e monitorowanie ci\u015Bnienia krwi pacjenta przez dob\u0119 lub trzy dni.",bloki:[{typ:"p",text:"Badanie Holtera, zar\xF3wno 24-godzinne, jak i 72-godzinne, to procedury diagnostyczne, kt\xF3re pozwalaj\u0105 na ci\u0105g\u0142e monitorowanie ci\u015Bnienia krwi pacjenta przez okre\u015Blony czas, zazwyczaj przez dob\u0119 lub trzy dni."},{typ:"p",text:"Obydwa rodzaje badania Holtera ci\u015Bnieniowego s\u0105 stosowane przede wszystkim w diagnostyce zaburze\u0144 ci\u015Bnienia krwi, takich jak nadci\u015Bnienie t\u0119tnicze, hipotensja ortostatyczna, arytmie oraz monitorowanie skuteczno\u015Bci leczenia nadci\u015Bnienia."},{typ:"warianty",items:["Ci\u015Bnieniowy 24h","Ci\u015Bnieniowy 72h"]}]},{slug:"badanie-ekg",nazwa:"Badanie EKG",kategoria:"Kardiologia",lead:"Podstawowe narz\u0119dzie diagnostyczne w kardiologii, rejestruj\u0105ce aktywno\u015B\u0107 elektryczn\u0105 serca.",bloki:[{typ:"p",text:"Badanie elektrokardiograficzne (EKG) spoczynkowe to procedura diagnostyczna, kt\xF3ra umo\u017Cliwia rejestrowanie aktywno\u015Bci elektrycznej serca w czasie spoczynku."},{typ:"p",text:"Badanie to jest podstawowym narz\u0119dziem diagnostycznym w kardiologii, kt\xF3re pozwala na szybk\u0105 i bezpieczn\u0105 ocen\u0119 stanu zdrowia serca oraz wykrywanie potencjalnych problem\xF3w kardiologicznych."}]},{slug:"badanie-usg",nazwa:"Badanie USG",kategoria:"Diagnostyka obrazowa",lead:"Procedura wykorzystuj\u0105ca fale d\u017Awi\u0119kowe o wysokiej cz\u0119stotliwo\u015Bci do wizualizacji tkanek wewn\u0119trznych.",bloki:[{typ:"p",text:"Badanie ultrasonograficzne (USG) jest procedur\u0105 diagnostyczn\u0105, kt\xF3ra wykorzystuje fale d\u017Awi\u0119kowe o wysokiej cz\u0119stotliwo\u015Bci do wizualizacji tkanek wewn\u0119trznych cia\u0142a pacjenta."},{typ:"p",text:"Badanie USG jest cennym narz\u0119dziem diagnostycznymi w r\xF3\u017Cnych obszarach medycyny, pozwalaj\u0105c lekarzom na dok\u0142adn\u0105 ocen\u0119 stanu zdrowia pacjent\xF3w oraz planowanie odpowiedniego leczenia i opieki medycznej."},{typ:"warianty",items:["Jamy brzusznej","Reumatologiczne staw\xF3w","Wykonanie echa serca"]}]},{slug:"leczenie-biologiczne",nazwa:"Leczenie biologiczne",kategoria:"Terapia biologiczna",lead:"Terapia lekami biologicznymi dla pacjent\xF3w z zaawansowanymi chorobami autoimmunologicznymi.",bloki:[{typ:"p",text:'Leczenie biologiczne stosuje si\u0119 w chorobach autoimmunologicznych. Polega na podawaniu pacjentowi preparat\xF3w biologicznych, kt\xF3rych zadaniem jest zmniejszenie odpowiedzi zapalnej w organizmie, czyli zmniejszenie nasilenia objaw\xF3w i zatrzymanie dalszego rozwoju choroby. Terapia lekami biologicznymi przeznaczona jest dla pacjent\xF3w z zaawansowanymi chorobami autoimmunologicznymi, opornymi na tak zwane "leczenie konwencjonalne" oraz kt\xF3rzy nie mog\u0105 wzi\u0105\u0107 udzia\u0142u w badaniach klinicznym.'},{typ:"p",text:"Wskaza\u0144 do leczenia biologicznego mo\u017Cna znale\u017A\u0107:"},{typ:"ul",items:["choroby reumatyczne (m.in. reumatoidalne zapalenie staw\xF3w, zesztywniaj\u0105ce zapalenie staw\xF3w kr\u0119gos\u0142upa, m\u0142odzie\u0144cze idiopatyczne zapalenie staw\xF3w, \u0142uszczycowe zapalenie staw\xF3w)","choroby zapalne jelit (choroba Le\u015Bniowskiego-Crohna, wrzodziej\u0105ce zapalenie jelita grubego)","choroby dermatologiczne (\u0142uszczyca, atopowe zapalenie sk\xF3ry, pokrzywka idiopatyczna)"]},{typ:"p",text:"W AmiCare Centrum Medycznym oferujemy Pa\u0144stwu dwa preparaty do terapii biologicznej:"},{typ:"warianty",items:["Yuflyma (adalimumab)","Remsima (infliksymab)"]},{typ:"p",text:"Ca\u0142y proces leczenia biologicznego w naszym O\u015Brodku przebiega zgodnie z aktualnymi wytycznymi pod nadzorem lekarzy specjalist\xF3w, maj\u0105cych do\u015Bwiadczenie w tym zakresie."},{typ:"cena",text:"Ustalana indywidualnie po pierwszej wizycie u specjalisty"}]}];export{a};
